package com.cangxu.wms.analytics.service;

import com.cangxu.wms.analytics.dto.AnalyticsOverview.ExperimentSummary;
import com.cangxu.wms.analytics.dto.AnalyticsOverview.StrategyResult;
import com.google.gson.Gson;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Service;

import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.List;

/**
 * Serves the result generated by {@code experiments/run_experiment.py}.
 * Keeping the experiment outside the application makes the numbers reproducible
 * and prevents the UI from silently inventing results.
 */
@Service
public class ExperimentService {

    private static final String RESOURCE = "experiments/algorithm-comparison.json";
    private final Gson gson = new Gson();

    public ExperimentSummary experiment() {
        ClassPathResource resource = new ClassPathResource(RESOURCE);
        if (!resource.exists()) {
            return fallback();
        }
        try (Reader reader = new InputStreamReader(resource.getInputStream(), StandardCharsets.UTF_8)) {
            ExperimentSummary result = gson.fromJson(reader, ExperimentSummary.class);
            return result == null ? fallback() : result;
        } catch (Exception e) {
            return fallback();
        }
    }

    private ExperimentSummary fallback() {
        return new ExperimentSummary(
                List.of(
                        new StrategyResult("随机上架", 0, 0, 0),
                        new StrategyResult("ABC 分类", 0, 0, 0),
                        new StrategyResult("AHP-TOPSIS", 0, 0, 0)
                ),
                0, 0, 0, 0, 0, 0, "", "missing");
    }
}
